//! Each CPU backend op against NumPy values (engine/tests/fixtures/ops.json,
//! generated by ref/gen_op_fixtures.py).

use engine::backend::cpu::Cpu;
use engine::backend::{Backend, Weight};
use engine::gguf::TensorType;
use serde_json::Value;

/// |got - want| <= TOL * max(1, |want|)
const TOL: f32 = 1e-5;

fn fixture(name: &str) -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/ops.json");
    let all: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    all[name].clone()
}

fn floats(v: &Value) -> Vec<f32> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap() as f32)
        .collect()
}

fn bytes(v: &Value) -> Vec<u8> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as u8)
        .collect()
}

fn int(v: &Value) -> usize {
    v.as_u64().unwrap() as usize
}

fn assert_close(got: &[f32], want: &Value) {
    let want = floats(want);
    assert_eq!(got.len(), want.len());
    for (i, (g, w)) in got.iter().zip(&want).enumerate() {
        assert!(
            (g - w).abs() <= TOL * w.abs().max(1.0),
            "index {i}: got {g}, want {w}"
        );
    }
}

fn weight<'a>(f: &Value, ty: TensorType, data: &'a [u8]) -> Weight<'a> {
    Weight {
        ty,
        rows: int(&f["rows"]),
        cols: int(&f["cols"]),
        data,
    }
}

#[test]
fn matvec() {
    for (name, ty) in [
        ("matvec_f32", TensorType::F32),
        ("matvec_bf16", TensorType::BF16),
    ] {
        let f = fixture(name);
        let data = bytes(&f["weight_bytes"]);
        let w = weight(&f, ty, &data);
        let mut out = vec![0.0; w.rows];
        Cpu.matvec(&w, &floats(&f["x"]), &mut out);
        assert_close(&out, &f["out"]);
    }
}

#[test]
fn embed() {
    let f = fixture("embed_bf16");
    let data = bytes(&f["weight_bytes"]);
    let w = weight(&f, TensorType::BF16, &data);
    let mut out = vec![0.0; w.cols];
    Cpu.embed(&w, int(&f["token"]) as u32, &mut out);
    // BF16 -> f32 is a bit shift: exact.
    assert_eq!(out, floats(&f["out"]));
}

#[test]
fn rms_norm() {
    let f = fixture("rms_norm");
    let x = floats(&f["x"]);
    let mut out = vec![0.0; x.len()];
    Cpu.rms_norm(
        &x,
        &floats(&f["weight"]),
        f["eps"].as_f64().unwrap() as f32,
        &mut out,
    );
    assert_close(&out, &f["out"]);
}

#[test]
fn rope() {
    let f = fixture("rope");
    let mut x = floats(&f["x"]);
    Cpu.rope(
        &mut x,
        int(&f["head_dim"]),
        int(&f["pos"]),
        f["freq_base"].as_f64().unwrap() as f32,
    );
    assert_close(&x, &f["out"]);
}

#[test]
fn attention() {
    let f = fixture("attention");
    let q = floats(&f["q"]);
    let mut out = vec![0.0; q.len()];
    Cpu.attention(
        &q,
        &floats(&f["k"]),
        &floats(&f["v"]),
        int(&f["n_head"]),
        int(&f["n_head_kv"]),
        int(&f["head_dim"]),
        &mut out,
    );
    assert!(out.iter().all(|v| v.is_finite()));
    assert_close(&out, &f["out"]);
}

#[test]
fn silu_mul() {
    let f = fixture("silu_mul");
    let gate = floats(&f["gate"]);
    let mut out = vec![0.0; gate.len()];
    Cpu.silu_mul(&gate, &floats(&f["up"]), &mut out);
    assert_close(&out, &f["out"]);
}

#[test]
fn add() {
    let f = fixture("add");
    let mut x = floats(&f["x"]);
    Cpu.add(&mut x, &floats(&f["y"]));
    assert_close(&x, &f["out"]);
}
